// Single source of truth for runtime release metadata: read the incumbent registry and
// the canonical crossfit summary, then write the generated runtime resource that the
// visual application fetches. Never duplicate release numbers by hand.
import { readFile, mkdir, writeFile } from 'node:fs/promises';
import { resolve, join } from 'node:path';
import { existsSync } from 'node:fs';
const visual = resolve(import.meta.dirname, '..');
let root = visual;
while (!existsSync(join(root, 'release/event_stack_incumbent.json'))) {
  const parent = resolve(root, '..');
  if (parent === root) throw new Error('Release registry not found above visual/');
  root = parent;
}
const promoted = JSON.parse(await readFile(join(root, 'release/event_stack_incumbent.json'), 'utf8'));
const summary = JSON.parse(await readFile(join(root, `outputs/crossfit/summary_${promoted.run_key}.json`), 'utf8'));
const output = { run_key: promoted.run_key, outer_metrics: summary.outer_metrics };
const target = join(visual, 'runtime/release-metadata.json');
await mkdir(resolve(target, '..'), { recursive: true });
await writeFile(target, JSON.stringify(output, null, 2) + '\n');
// The application imports the same data as a generated module, so the standalone
// page needs no fetch at all (works from file://).
const modulePath = join(visual, 'app/src/runtime/release-data.generated.ts');
await writeFile(modulePath,
  '// Generated by tools/prepare-release.mjs from the incumbent registry + crossfit summary.\n' +
  '// Do not edit by hand; run `npm run build` (or predev/prebuild) to refresh.\n' +
  'export type ReleaseMetrics = {\n' +
  '  run_key: string;\n' +
  '  outer_metrics: { f1: number; ppv: number; sensitivity: number; n_tp: number; n_true: number; n_pred: number };\n' +
  '};\n\n' +
  'export const RELEASE_METADATA: ReleaseMetrics = ' + JSON.stringify(output, null, 2) + ';\n');
console.log(`Prepared release metadata for ${promoted.run_key}`);
